css:
.gp { width: 72mm; margin: 0 auto; color: #000; background: #fff;
      font-family: "Helvetica Neue", Arial, sans-serif; font-size: 11px; line-height: 1.35;
      -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.gp * { box-sizing: border-box; }
.gp .mono { font-family: "Courier New", ui-monospace, monospace; }

.gp-head { text-align: center; padding-bottom: 3px; }
.gp-logo { max-height: 34px; max-width: 55%; display: block; margin: 0 auto 3px;
           filter: grayscale(1) contrast(1.5); }
.gp-inst { font-weight: 700; font-size: 13px; text-transform: uppercase; letter-spacing: .3px; }
.gp-college { font-size: 10px; margin-top: 1px; }

.gp-title { text-align: center; font-weight: 700; font-size: 12px; letter-spacing: 1.5px;
            border-top: 1.5px solid #000; border-bottom: 1.5px solid #000; padding: 3px 0; margin: 5px 0; }

.gp-meta { display: flex; justify-content: space-between; font-size: 9.5px; margin-bottom: 5px; }

.gp-photo-wrap { text-align: center; margin: 2px 0 6px; }
.gp-photo { width: 30mm; height: 38mm; object-fit: cover; border: 1px solid #000; padding: 2px;
            background: #fff; filter: grayscale(1) contrast(1.1); }

.gp-name { text-align: center; font-weight: 700; font-size: 15px; letter-spacing: .3px; margin-bottom: 5px; }

.gp-rows { border-top: 1px dashed #000; padding-top: 4px; }
.gp-rows .r { display: flex; justify-content: space-between; gap: 10px; padding: 1.5px 0; }
.gp-rows .k { font-weight: 600; white-space: nowrap; }
.gp-rows .v { text-align: right; overflow-wrap: anywhere; }

.gp-intime { display: flex; justify-content: space-between; align-items: center;
             border-top: 1px dashed #000; border-bottom: 1px dashed #000; margin-top: 5px;
             padding: 4px 2px; font-weight: 700; }
.gp-intime .lbl { letter-spacing: 1.5px; font-size: 11px; }
.gp-intime .val { font-size: 13px; }

.gp-attend { font-size: 10px; margin-top: 6px; }

.gp-sign { margin-top: 16px; }
.gp-sign .sign-line { border-top: 1px solid #000; width: 55%; }
.gp-sign .sign-cap { font-size: 9px; padding-top: 2px; }

.gp-foot { text-align: center; font-size: 9px; line-height: 1.3; margin-top: 12px;
           padding-top: 4px; border-top: 1px dashed #000; }

@media print {
  @page { size: 80mm auto; margin: 3mm; }
  html, body { width: 80mm; margin: 0 !important; padding: 0 !important; background: #fff; }
}
